import json

from zscaler.zpa.policies import PolicySetControllerAPI

CONFIG = {"client": {"customerId": "<id>"}}


class StubResponse:
    def __init__(self, body):
        self._body = body

    def get_body(self):
        return self._body

    def get_status(self):
        return 200


class StubExecutor:
    """Stands in for RequestExecutor: records requests, replies with canned bodies."""

    def __init__(self):
        self.requests = []

    def create_request(self, method, endpoint, body=None, headers=None, params=None,
                       use_raw_data_for_body=False):
        req = {"method": method, "endpoint": endpoint.strip(),
               "body": {} if body is None else body, "params": params or {}}
        self.requests.append(req)
        return req, None

    def execute(self, request, response_type=None, return_raw_response=False):
        if "policySet/policyType/" in request["endpoint"]:
            return StubResponse({"id": "<id>", "policyType": "2"}), None
        return StubResponse({"id": "<id>", "name": "rule-a",
                             "action": "RE_AUTH"}), None


ex = StubExecutor()
rule, resp, err = PolicySetControllerAPI(ex, CONFIG).add_timeout_rule_v2(
    name="rule-a",
    action="isolate",                       # accepted by **kwargs, never used
    conditions=[("client_type", ["zpn_client_type_exporter"])],
)

post = [r for r in ex.requests if r["method"] == "POST"][0]
print("err =", err)
print("caller passed action='isolate'; POST body action ->",
      json.dumps(post["body"].get("action")))
print("full POST body:", json.dumps(post["body"], indent=2, sort_keys=True))

